preConditionHook:
// EL: bullFail = CountIF(close[1] < open[1] and close > open, lookback);
//     bearFail = CountIF(close[1] > open[1] and close < open, lookback);
// CountIF counts over bars 0..N-1 INCLUDING the current bar, and the counted
// condition is a true SERIES: its own [1] offsets shift with the counted bar
// (EL_FEATURES `countif`, VERIFIED -- the frozen-offset model was refuted), so
// position i tests close[i+1]/open[i+1] against close[i]/open[i]. That is the
// TailBarCountDominance construction, and the deepest bar read is lookback.
// The counted operands are prices, which have real history back to the chart
// start, so no zero-filled variable mirror is needed. The counts are EL numeric
// variables and stay doubles. A tie bar closes in neither direction and
// satisfies neither half of a pair.
// Both counters persist across bars, so they are reset before the loop.
bullFail = 0.0;
bearFail = 0.0;
for (int i = 0; i < (int)lookback; ++i) {
    if (el_lt(close[i + 1], open[i + 1]) && el_gt(close[i], open[i])) {
        bullFail += 1;
    }
    if (el_gt(close[i + 1], open[i + 1]) && el_lt(close[i], open[i])) {
        bearFail += 1;
    }
}
